	draw(i*v -- i*v + (4 - i)*h);
    draw(i*h -- i*h + (4 - i)*v);
    draw((i + 1)*h -- (i + 1)*h + (i + 1)*d);
}

draw(h + v -- v -- (0, 0) -- 2*h -- 2*h + v -- h + 2*v -- 2*v -- 4*v -- 3*h + v -- 3*h -- 4*h, linewidth(2));
